import React, { useState } from 'react';
import './app.css';
import CommandInput from './components/CommandInput';
import CommandOutput from './components/CommandOutput';
import FileUploader from './components/FileUploader';
import ReportsViewer from './components/ReportsViewer';
import './components/ReportsViewer.css'; // Importar los estilos

function App() {
  const [commands, setCommands] = useState('');
  const [output, setOutput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [activeTab, setActiveTab] = useState('commands'); // 'commands' o 'reports'

  const handleFileLoad = (fileContent) => {
    setCommands(fileContent);
  };

  const executeCommands = async () => {
    if (!commands.trim()) {
      setOutput('No hay comandos para ejecutar.');
      return;
    }

    setIsLoading(true);
    setOutput('');

    const lines = commands.split(/\r?\n/);
    // contar comandos válidos (no vacías y no comentarios) para numeración
    const validTotal = lines.filter(l => l.trim() !== '' && !l.trim().startsWith('#')).length;
    let cmdCount = 0;
    const resultLines = [];

    try {
      for (let i = 0; i < lines.length; i++) {
        const raw = lines[i];
        const trimmed = raw.trim();
        const lineNumber = i + 1;

        // línea vacía -> conservar
        if (trimmed === '') {
          resultLines.push('');
          setOutput(resultLines.join('\n'));
          continue;
        }

        // comentario -> mostrar en su lugar (no se envía al servidor)
        if (trimmed.startsWith('#')) {
          resultLines.push(trimmed);
          setOutput(resultLines.join('\n'));
          continue;
        }

        // es un comando válido
        cmdCount++;
        // encabezado con numeración y línea original
        resultLines.push(`\n[Comando ${cmdCount}/${validTotal} - Línea ${lineNumber}] ${raw}`);
        setOutput(resultLines.join('\n'));

        // enviar solo esta línea al servidor
        const resp = await fetch('http://localhost:8080/execute', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ commands: raw })
        });

        if (!resp.ok) {
          resultLines.push(`Error del servidor: ${resp.status}`);
          setOutput(resultLines.join('\n'));
          continue;
        }

        const json = await resp.json();
        if (json.output) {
          // agregar la salida tal cual la devuelve el backend
          resultLines.push(json.output);
        } else if (json.error) {
          resultLines.push(`Error: ${json.error}`);
        } else {
          resultLines.push('(sin salida)');
        }

        // separador visual opcional
        resultLines.push('\n---\n');
        setOutput(resultLines.join('\n'));
      }

      // resumen final opcional si quieres (descomentar si lo deseas)
      // resultLines.push(`\n=== RESUMEN ===\nComandos ejecutados: ${cmdCount} / ${validTotal}`);
      // setOutput(resultLines.join('\n'));
    } catch (err) {
      resultLines.push(`Error de conexión: ${err.message}`);
      setOutput(resultLines.join('\n'));
    } finally {
      setIsLoading(false);
    }
  };

  const clearCommands = () => {
    setCommands('');
  };

  const clearOutput = () => {
    setOutput('');
  };

  return (
    <div className="App">
      <header className="App-header">
        <h1>MIA - Sistema de Archivos</h1>
        <p>Proyecto 1 - Manejo e Implementación de Archivos</p>

        {/* Menú de navegación entre pestañas */}
        <nav className="app-nav">
          <button 
            className={`nav-tab ${activeTab === 'commands' ? 'active' : ''}`}
            onClick={() => setActiveTab('commands')}
          >
            Comandos
          </button>
          <button 
            className={`nav-tab ${activeTab === 'reports' ? 'active' : ''}`}
            onClick={() => setActiveTab('reports')}
          >
            Reportes
          </button>
        </nav>
      </header>

      <main className="App-main">
        {activeTab === 'commands' ? (
          <div className="container">
            <div className="input-section">
              <div className="section-header">
                <h2>Área de Entrada de Comandos</h2>
                <div className="button-group">
                  <FileUploader onFileLoad={handleFileLoad} />
                  <button onClick={clearCommands} className="btn-secondary">
                    Limpiar
                  </button>
                </div>
              </div>

              <CommandInput 
                value={commands}
                onChange={setCommands}
                placeholder="Ingresa los comandos aquí, uno por línea:

Ejemplo:
mkdisk -size=3000 -unit=k -path=disk1.mia
mkdisk -size=5000 -unit=m -path=disk2.mia
fdisk -size=1000 -path=disk1.mia -name=part1

# Los comentarios empiezan con #
# Cada línea es un comando separado"
              />

              <div className="execute-section">
                <button 
                  onClick={executeCommands}
                  disabled={isLoading || !commands.trim()}
                  className="btn-execute"
                >
                  {isLoading ? 'Ejecutando...' : 'Ejecutar Comandos'}
                </button>
              </div>
            </div>

            <div className="output-section">
              <div className="section-header">
                <h2>Área de Salida de Comandos</h2>
                <button onClick={clearOutput} className="btn-secondary">
                  Limpiar Salida
                </button>
              </div>

              <CommandOutput 
                output={output}
                isLoading={isLoading}
              />
            </div>
          </div>
        ) : (
          <ReportsViewer />
        )}
      </main>
    </div>
  );
}

export default App;
